PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('buyer','owner','staff')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,cost INTEGER NOT NULL CHECK(cost>0),retail INTEGER NOT NULL CHECK(retail>0),floor INTEGER NOT NULL CHECK(floor>0),stock INTEGER NOT NULL CHECK(stock>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),sold INTEGER NOT NULL DEFAULT 0,returned INTEGER NOT NULL DEFAULT 0,unavailable INTEGER NOT NULL DEFAULT 0 CHECK(unavailable>=0 AND unavailable<=stock-reserved),age_days INTEGER NOT NULL,quality INTEGER NOT NULL,discount_bps INTEGER NOT NULL,margin_bps INTEGER NOT NULL,clearance INTEGER NOT NULL,tags TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS missions(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,goal TEXT NOT NULL,budget INTEGER NOT NULL,required TEXT NOT NULL,quantity INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_actions(id TEXT PRIMARY KEY,mission_id TEXT NOT NULL REFERENCES missions(id),tool TEXT NOT NULL,summary TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,status TEXT NOT NULL,total INTEGER NOT NULL,retail INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'USD',expires INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_lines(quote_id TEXT NOT NULL REFERENCES quotes(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,category TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL,retail INTEGER NOT NULL,cost INTEGER NOT NULL,PRIMARY KEY(quote_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id),paypal_id TEXT UNIQUE,capture_id TEXT UNIQUE,status TEXT NOT NULL,refund_id TEXT,refunded INTEGER NOT NULL DEFAULT 0,error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_events(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),kind TEXT NOT NULL,provider_status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS return_requests(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'REQUESTED',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,discount_bps INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS quotes_session ON quotes(session_id);
CREATE INDEX IF NOT EXISTS missions_session ON missions(session_id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
